; Wizard sound driver - Doraemon no Quiz Boy (J) (V1.0) [C][!]
; bank 4 $4000-$7C19 and bank 0 $3270-$3A6F
; Generated by tools/wiz_gen.py. Assembles byte-identical with RGBDS 1.0.0.

INCLUDE "wizard_sound.inc"

; ---- WRAM ----
DEF wSndPause        EQU $C963   ;   1 byte: non-zero: music structs neither tick nor write registers
DEF wSndPan          EQU $C964   ;   8 bytes: NR51 bits per struct (cmds $8A-$8C)
DEF wSndMasterVol    EQU $C96C   ;   1 byte: NR50 copy (fade)
DEF wSndFadeOn       EQU $C96D   ;   1 byte: 1 = fade running
DEF wSndFadeRate     EQU $C96E   ;   1 byte: frames per fade step
DEF wSndFadeCount    EQU $C96F   ;   1 byte: fade frame counter
DEF wSndUnused0D     EQU $C970   ;   2 bytes: not used
DEF wSndChIdx        EQU $C972   ;   1 byte: struct being processed (0-7)
DEF wSndLastMask     EQU $C973   ;   1 byte: channel mask of the last sound started
DEF wSndNote         EQU $C974   ;   1 byte: note byte being read
DEF wSndRawFlag      EQU $C975   ;   1 byte: compared with $7D, never written by the driver
DEF wSndActive       EQU $C976   ;   1 byte: bit n = struct n running (0-3 music ch1-4, 4-7 SFX ch1-4)
DEF wSndTracks       EQU $C977   ; 272 bytes: 8 structs of $22 bytes

SECTION "Wizard sound driver", ROMX[$4000], BANK[4]

; Pause music: structs 0-3 stop ticking and writing registers (SFX keep running). Not called by either game.
Sound_Pause::
    push af                                         ; 4000
    ld a,$01                                        ; 4001
    ld [wSndPause],a                                ; 4003
    pop af                                          ; 4006
    ret                                             ; 4007

; Undo Sound_Pause. Not called by either game.
Sound_Resume::
    push af                                         ; 4008
    sub a                                           ; 4009
    ld [wSndPause],a                                ; 400A
    pop af                                          ; 400D
    ret                                             ; 400E

; Boot: sound on, NR51=0, NR50=$77, ch3 DAC on, all structs stopped, pan bytes reset.
Sound_Init::
    ld a,$80                                        ; 400F
    ldh [rNR52],a                                   ; 4011  NR52: sound on
    ld a,$00                                        ; 4013
    ldh [rNR51],a                                   ; 4015  NR51: all channels off
    ld a,$77                                        ; 4017
    ld [wSndMasterVol],a                            ; 4019
    ldh [rNR50],a                                   ; 401C  NR50: full volume
    ldh a,[rNR30]                                   ; 401E
    or $80                                          ; 4020
    ldh [rNR30],a                                   ; 4022  NR30: ch3 DAC on
    sub a                                           ; 4024
    ld [wSndActive],a                               ; 4025  no struct running
    sub a                                           ; 4028
    ld [wSndTracks + 0 * TRK_SIZE + TRK_FLAGS],a    ; 4029  clear TRK_FLAGS of all 8 structs
    ld [wSndTracks + 1 * TRK_SIZE + TRK_FLAGS],a    ; 402C
    ld [wSndTracks + 2 * TRK_SIZE + TRK_FLAGS],a    ; 402F
    ld [wSndTracks + 3 * TRK_SIZE + TRK_FLAGS],a    ; 4032
    ld [wSndTracks + 4 * TRK_SIZE + TRK_FLAGS],a    ; 4035
    ld [wSndTracks + 5 * TRK_SIZE + TRK_FLAGS],a    ; 4038
    ld [wSndTracks + 6 * TRK_SIZE + TRK_FLAGS],a    ; 403B
    ld [wSndTracks + 7 * TRK_SIZE + TRK_FLAGS],a    ; 403E
    ld a,$11                                        ; 4041  pan bytes: $11,$22,$44,$88 for structs 0-3 and 4-7
    ld b,$04                                        ; 4043
    ld hl,wSndPan                                   ; 4045
    ld de,wSndPan + 4                               ; 4048
.l404B:
    ld [hli],a                                      ; 404B
    ld [de],a                                       ; 404C
    inc de                                          ; 404D
    sla a                                           ; 404E
    dec b                                           ; 4050
    jr nz,.l404B                                    ; 4051
    ret                                             ; 4053

; a = frames per step. Each step lowers both NR50 volumes by 1 (stops at 0). Ends only through Sound_StopAll.
Sound_FadeOut::
    ld [wSndFadeRate],a                             ; 4054  frames per step
    ld a,$01                                        ; 4057
    ld [wSndFadeOn],a                               ; 4059  fade on
    dec a                                           ; 405C
    ld [wSndFadeCount],a                            ; 405D  counter = 0
    ret                                             ; 4060

; a = value, b = struct mask: TRK_VOLOFS of each struct whose bit is set = a. Not called by either game.
Sound_SetVolOffset::
    ld c,$08                                        ; 4061  8 structs
    ld hl,wSndTracks + 0 * TRK_SIZE + TRK_VOLOFS    ; 4063
.l4066:
    push af                                         ; 4066
    bit 0,b                                         ; 4067
    jr z,.l406C                                     ; 4069
    ld [hl],a                                       ; 406B  TRK_VOLOFS = a
.l406C:
    pop af                                          ; 406C
    ld de,TRK_SIZE                                  ; 406D
    add hl,de                                       ; 4070
    srl b                                           ; 4071
    dec c                                           ; 4073
    jr nz,.l4066                                    ; 4074
    ret                                             ; 4076

; Stop every struct, silence the channels, cancel the fade, NR50=$77.
Sound_StopAll::
    sub a                                           ; 4077  keep nothing

; a = mask of structs to keep (StopAll enters with a=0). Not called directly by either game.
Sound_StopExcept::
    ld c,a                                          ; 4078
    ld a,[wSndActive]                               ; 4079
    and c                                           ; 407C
    ld [wSndActive],a                               ; 407D  wSndActive &= keep mask
    ld e,$EE                                        ; 4080  NR51 mask for ch1 (rotated each pass)
    ld d,$FE                                        ; 4082  NR52 mask for ch1 (writing it has no effect)
    ld b,$04                                        ; 4084
.l4086:
    ld a,c                                          ; 4086
    bit 0,a                                         ; 4087  music bit of this channel kept?
    jr z,.l408F                                     ; 4089
    bit 4,a                                         ; 408B  and its SFX bit kept? then leave the channel alone
    jr nz,.l4099                                    ; 408D
.l408F:
    ldh a,[rNR51]                                   ; 408F  take the channel out of NR51
    and e                                           ; 4091
    ldh [rNR51],a                                   ; 4092
    ldh a,[rNR52]                                   ; 4094
    and d                                           ; 4096
    ldh [rNR52],a                                   ; 4097
.l4099:
    rr c                                            ; 4099
    ld a,e                                          ; 409B
    rlca                                            ; 409C
    ld e,a                                          ; 409D
    ld a,d                                          ; 409E
    rlca                                            ; 409F
    ld d,a                                          ; 40A0
    dec b                                           ; 40A1
    jr nz,.l4086                                    ; 40A2
    sub a                                           ; 40A4
    ld [wSndFadeOn],a                               ; 40A5  fade off
    ld a,$77                                        ; 40A8
    ld [wSndMasterVol],a                            ; 40AA
    ldh [rNR50],a                                   ; 40AD  NR50 = $77
    ret                                             ; 40AF

; c = sound id. Starts the tracks listed in the header Snd_SoundTable[c].
Sound_Play::
    ld b,$00                                        ; 40B0
    ld hl,Snd_SoundTable                            ; 40B2  Snd_SoundTable[c] -> header
    add hl,bc                                       ; 40B5
    add hl,bc                                       ; 40B6
    ld a,[hli]                                      ; 40B7
    ld h,[hl]                                       ; 40B8
    ld l,a                                          ; 40B9
    ld a,[hl]                                       ; 40BA  header byte 0: struct mask
    ld c,a                                          ; 40BB
    ld [wSndLastMask],a                             ; 40BC  header byte 0: struct mask
    and $F0                                         ; 40BF  any SFX struct in the mask?
    jr nz,.l40CE                                    ; 40C1
    ld a,[$C3F8]                                    ; 40C3  music only: game flag (sound option?) set -> ignore the request
    and a                                           ; 40C6
    ret nz                                          ; 40C7
    ld a,c                                          ; 40C8
    push af                                         ; 40C9
    sub a                                           ; 40CA  music only: NR51 = 0
    ldh [rNR51],a                                   ; 40CB
    pop af                                          ; 40CD
.l40CE:
    ld b,$08                                        ; 40CE
    inc hl                                          ; 40D0
    ld de,wSndTracks + 0 * TRK_SIZE + TRK_PTR       ; 40D1  struct 0
.l40D4:
    bit 0,c                                         ; 40D4
    jr z,.l40E3                                     ; 40D6
    push hl                                         ; 40D8
    push de                                         ; 40D9
    push bc                                         ; 40DA
    call Snd_InitTrack                              ; 40DB  start this struct from the next header word
    pop bc                                          ; 40DE
    pop de                                          ; 40DF
    pop hl                                          ; 40E0
    inc hl                                          ; 40E1
    inc hl                                          ; 40E2
.l40E3:
    rr c                                            ; 40E3
    push bc                                         ; 40E5
    push hl                                         ; 40E6
    ld hl,TRK_SIZE                                  ; 40E7
    add hl,de                                       ; 40EA
    ld e,l                                          ; 40EB
    ld d,h                                          ; 40EC
    pop hl                                          ; 40ED
    pop bc                                          ; 40EE
    dec b                                           ; 40EF
    jr nz,.l40D4                                    ; 40F0
    ld a,[wSndLastMask]                             ; 40F2
    and $F0                                         ; 40F5  any SFX struct in the mask?
    jr z,.l4105                                     ; 40F7
    ld a,[wSndLastMask]                             ; 40F9
    ld c,a                                          ; 40FC
    ld a,[wSndActive]                               ; 40FD
    or c                                            ; 4100
    ld [wSndActive],a                               ; 4101  SFX: add to the running structs
    ret                                             ; 4104
.l4105:
    ld a,[wSndLastMask]                             ; 4105
    ld [wSndActive],a                               ; 4108  music: replaces everything, SFX included
    ret                                             ; 410B

; de = struct, hl -> track pointer in the header. Clears the struct and arms it for an immediate first row.
Snd_InitTrack:
    ld a,[hli]                                      ; 410C
    ld [de],a                                       ; 410D  TRK_PTR = track
    inc de                                          ; 410E
    ld a,[hl]                                       ; 410F
    ld [de],a                                       ; 4110
    ld l,e                                          ; 4111
    ld h,d                                          ; 4112
    inc hl                                          ; 4113
    ld a,$01                                        ; 4114  TRK_LENGTH = 1, TRK_GATE = 1
    ld c,$00                                        ; 4116
    ld [hli],a                                      ; 4118
    ld [hl],c                                       ; 4119
    inc hl                                          ; 411A
    ld [hli],a                                      ; 411B
    ld [hl],c                                       ; 411C
    inc hl                                          ; 411D
    sub a                                           ; 411E
    ld [hli],a                                      ; 411F  TRK_VOLUME, +7, +8, TRK_DUTY = 0
    ld [hli],a                                      ; 4120
    ld [hli],a                                      ; 4121
    ld [hli],a                                      ; 4122
    ld a,$06                                        ; 4123
    ld [hl],a                                       ; 4125  TRK_FLAGS = 6 (bits 1,2: never read)
    ld bc,$0005                                     ; 4126
    add hl,bc                                       ; 4129
    ld e,l                                          ; 412A
    ld d,h                                          ; 412B
    dec hl                                          ; 412C
    ld [hl],d                                       ; 412D
    dec hl                                          ; 412E
    ld [hl],e                                       ; 412F  TRK_SP = TRK_STACK
    ld de,$000E                                     ; 4130
    add hl,de                                       ; 4133
    sub a                                           ; 4134
    ld [hli],a                                      ; 4135  clear both envelopes (pos + pointer)
    ld [hli],a                                      ; 4136
    ld [hli],a                                      ; 4137
    ld [hli],a                                      ; 4138
    ld [hli],a                                      ; 4139
    ld [hli],a                                      ; 413A
    ret                                             ; 413B

; Call once per frame: fade, then tick every running struct, then write the registers.
Sound_Update::
    ld a,[wSndFadeOn]                               ; 413C  fade running?
    cp $01                                          ; 413F
    jr nz,.l4171                                    ; 4141
    ld a,[wSndFadeRate]                             ; 4143
    ld c,a                                          ; 4146
    ld a,[wSndFadeCount]                            ; 4147
    inc a                                           ; 414A
    ld [wSndFadeCount],a                            ; 414B
    cp c                                            ; 414E  step every wSndFadeRate frames
    jr c,.l4171                                     ; 414F
    sub a                                           ; 4151
    ld [wSndFadeCount],a                            ; 4152
    ld a,[wSndMasterVol]                            ; 4155
    ld e,a                                          ; 4158
    and $88                                         ; 4159  keep the VIN bits
    ld c,a                                          ; 415B
    ld a,e                                          ; 415C
    and $07                                         ; 415D
    jr z,.l4162                                     ; 415F
    dec a                                           ; 4161  right volume - 1 (min 0)
.l4162:
    ld d,a                                          ; 4162
    ld a,e                                          ; 4163
    and $70                                         ; 4164
    jr z,.l416A                                     ; 4166
    sub $10                                         ; 4168  left volume - 1 (min 0)
.l416A:
    or d                                            ; 416A
    or c                                            ; 416B
    ld [wSndMasterVol],a                            ; 416C
    ldh [rNR50],a                                   ; 416F
.l4171:
    sub a                                           ; 4171
    ld [wSndChIdx],a                                ; 4172  struct 0
    ld a,[wSndActive]                               ; 4175
    ld hl,wSndTracks + 0 * TRK_SIZE + TRK_PTR       ; 4178
    ld c,a                                          ; 417B
.l417C:
    bit 0,c                                         ; 417C  running?
    jr z,.l4195                                     ; 417E
    push hl                                         ; 4180
    push bc                                         ; 4181
    ld a,[wSndChIdx]                                ; 4182
    cp $04                                          ; 4185  music struct and paused: no tick
    jr nc,.l4190                                    ; 4187
    ld a,[wSndPause]                                ; 4189
    and $01                                         ; 418C
    jr nz,.l4193                                    ; 418E
.l4190:
    call Snd_TickTrack                              ; 4190  tick it
.l4193:
    pop bc                                          ; 4193
    pop hl                                          ; 4194
.l4195:
    ld de,TRK_SIZE                                  ; 4195
    add hl,de                                       ; 4198
    rr c                                            ; 4199
    ld a,[wSndChIdx]                                ; 419B
    inc a                                           ; 419E
    ld [wSndChIdx],a                                ; 419F
    cp $08                                          ; 41A2
    jr c,.l417C                                     ; 41A4
    call Snd_OutputAll                              ; 41A6  then write the registers
    ret                                             ; 41A9

; Output pass: Snd_OutputChannel for structs 0-7.
Snd_OutputAll:
    ld a,[wSndActive]                               ; 41AA
    ld b,a                                          ; 41AD
    ld c,$00                                        ; 41AE
    ld hl,wSndTracks + 0 * TRK_SIZE + TRK_PTR       ; 41B0
.l41B3:
    push bc                                         ; 41B3
    push hl                                         ; 41B4
    call Snd_OutputChannel                          ; 41B5
    pop hl                                          ; 41B8
    pop bc                                          ; 41B9
    ld de,TRK_SIZE                                  ; 41BA
    add hl,de                                       ; 41BD
    srl b                                           ; 41BE
    inc c                                           ; 41C0
    ld a,c                                          ; 41C1
    cp $08                                          ; 41C2
    jr c,.l41B3                                     ; 41C4
    ret                                             ; 41C6

; hl = struct, c = struct index, b = active mask shifted so bit 0 = this struct.
Snd_OutputChannel:
    ld a,c                                          ; 41C7
    cp $04                                          ; 41C8
    jr nc,.l41D6                                    ; 41CA  music struct:
    ld a,[wSndPause]                                ; 41CC
    and a                                           ; 41CF
    ret nz                                          ; 41D0    paused: nothing
    bit 4,b                                         ; 41D1    SFX running on this channel: nothing
    jr z,.l41D6                                     ; 41D3
    ret                                             ; 41D5
.l41D6:
    bit 0,b                                         ; 41D6  struct not running
    ret z                                           ; 41D8
    ld b,$00                                        ; 41D9
    ld a,c                                          ; 41DB
    push hl                                         ; 41DC
    ld hl,Snd_NRx2Table                             ; 41DD  c = NRx2 of the channel
    add hl,bc                                       ; 41E0
    ld c,[hl]                                       ; 41E1
    pop hl                                          ; 41E2
    ld b,a                                          ; 41E3
    ld de,$000A                                     ; 41E4
    add hl,de                                       ; 41E7
    bit 0,[hl]                                      ; 41E8  TRK_FLAGS bit 0: note sounding?
    jp z,Snd_OutputOff                              ; 41EA
    push hl                                         ; 41ED
    ld de,$0014                                     ; 41EE  pitch envelope:
    add hl,de                                       ; 41F1
.l41F2:
    ld a,[hli]                                      ; 41F2  e = position
    ld e,a                                          ; 41F3
    inc hl                                          ; 41F4
    ld a,[hld]                                      ; 41F5
    and a                                           ; 41F6  no pitch envelope
    jr z,.l4239                                     ; 41F7
    push hl                                         ; 41F9
    ld l,[hl]                                       ; 41FA
    ld h,a                                          ; 41FB
    ld d,$00                                        ; 41FC
    add hl,de                                       ; 41FE
    ld a,[hl]                                       ; 41FF
    cp $81                                          ; 4200  $81: restart
    jr nz,.l420A                                    ; 4202
    pop hl                                          ; 4204
    dec hl                                          ; 4205
    ld [hl],$00                                     ; 4206
    jr .l41F2                                       ; 4208
.l420A:
    cp $80                                          ; 420A  $80: hold (repeat previous value)
    jr nz,.l4213                                    ; 420C
    pop hl                                          ; 420E
    dec hl                                          ; 420F
    dec [hl]                                        ; 4210
    jr .l41F2                                       ; 4211
.l4213:
    pop hl                                          ; 4213
    dec hl                                          ; 4214
    ld de,$FFED                                     ; 4215  de = TRK_PERIOD
    add hl,de                                       ; 4218
    ld e,[hl]                                       ; 4219
    inc hl                                          ; 421A
    ld d,[hl]                                       ; 421B
    bit 7,a                                         ; 421C  add the signed step
    jr z,.l4227                                     ; 421E
    add a,e                                         ; 4220
    ld e,a                                          ; 4221
    ld a,$FF                                        ; 4222  BUG: d not updated, NRx4 below gets the old high byte
    adc a,d                                         ; 4224
    jr .l422D                                       ; 4225
.l4227:
    add a,e                                         ; 4227
    ld e,a                                          ; 4228
    ld a,$00                                        ; 4229
    adc a,d                                         ; 422B
    ld d,a                                          ; 422C
.l422D:
    ld [hld],a                                      ; 422D  TRK_PERIOD += step
    ld [hl],e                                       ; 422E
    inc c                                           ; 422F
    ld a,e                                          ; 4230
    ldh [c],a                                       ; 4231  NRx3 (overwritten below in the same frame)
    inc c                                           ; 4232
    ld a,d                                          ; 4233
    and $07                                         ; 4234
    ldh [c],a                                       ; 4236
    dec c                                           ; 4237
    dec c                                           ; 4238
.l4239:
    pop hl                                          ; 4239
    ld de,$0011                                     ; 423A  volume envelope:
    add hl,de                                       ; 423D
.l423E:
    push hl                                         ; 423E
    ld e,$00                                        ; 423F
    ld d,[hl]                                       ; 4241  d = position
    inc hl                                          ; 4242
    inc hl                                          ; 4243
    ld a,[hld]                                      ; 4244
    and a                                           ; 4245
    jp z,.l42E5                                     ; 4246  no volume envelope
    ld e,d                                          ; 4249
    ld d,a                                          ; 424A
    ld l,[hl]                                       ; 424B
    ld h,d                                          ; 424C
    ld d,$00                                        ; 424D
    add hl,de                                       ; 424F
    ld a,[hl]                                       ; 4250
    cp $80                                          ; 4251  $80: hold
    jr nz,.l4259                                    ; 4253
    pop hl                                          ; 4255
    dec [hl]                                        ; 4256
    jr .l423E                                       ; 4257
.l4259:
    cp $81                                          ; 4259  $81: restart
    jr nz,.l4262                                    ; 425B
    pop hl                                          ; 425D
    ld [hl],$00                                     ; 425E
    jr .l423E                                       ; 4260
.l4262:
    pop hl                                          ; 4262
    ld de,$FFEB                                     ; 4263
    add hl,de                                       ; 4266
    push hl                                         ; 4267
    ld e,a                                          ; 4268
    push de                                         ; 4269
    ld a,[hl]                                       ; 426A  TRK_VOLUME >> 4
    swap a                                          ; 426B
    and $0F                                         ; 426D
    ld de,$001B                                     ; 426F
    add hl,de                                       ; 4272
    add a,[hl]                                      ; 4273  + TRK_VOLOFS
    cp $10                                          ; 4274  clamp: >= $F0 -> 0, $10-$EF -> 15
    jr c,.l4281                                     ; 4276
    cp $F0                                          ; 4278
    jr c,.l427F                                     ; 427A
    sub a                                           ; 427C
    jr .l4281                                       ; 427D
.l427F:
    ld a,$0F                                        ; 427F
.l4281:
    add a,a                                         ; 4281  Snd_VolumeTable[vol][env value]
    add a,a                                         ; 4282
    add a,a                                         ; 4283
    ld e,a                                          ; 4284
    ld d,$00                                        ; 4285
    ld hl,Snd_VolumeTable                           ; 4287
    add hl,de                                       ; 428A
    add hl,de                                       ; 428B
    pop de                                          ; 428C
    ld d,$00                                        ; 428D
    add hl,de                                       ; 428F
    ld e,[hl]                                       ; 4290
    push de                                         ; 4291
    ld e,b                                          ; 4292
    ld d,$00                                        ; 4293
    ld hl,wSndPan                                   ; 4295  NR51 |= pan
    add hl,de                                       ; 4298
    ldh a,[rNR51]                                   ; 4299
    or [hl]                                         ; 429B
    ldh [rNR51],a                                   ; 429C
    pop de                                          ; 429E
    ld a,c                                          ; 429F
    cp $1C                                          ; 42A0  ch3: NR32 from Snd_WaveVolTable
    jr nz,.l42B2                                    ; 42A2
    ld a,e                                          ; 42A4
    and $0F                                         ; 42A5
    ld d,$00                                        ; 42A7
    push hl                                         ; 42A9
    ld hl,Snd_WaveVolTable                          ; 42AA
    add hl,de                                       ; 42AD
    ld a,[hl]                                       ; 42AE
    pop hl                                          ; 42AF
    jr .l42B5                                       ; 42B0
.l42B2:
    ld a,e                                          ; 42B2
    swap a                                          ; 42B3  others: NRx2 = level << 4 (no hardware envelope)
.l42B5:
    ldh [c],a                                       ; 42B5
    pop hl                                          ; 42B6
    ld de,$0003                                     ; 42B7
    add hl,de                                       ; 42BA
    dec c                                           ; 42BB
    ld a,c                                          ; 42BC
    cp $1A                                          ; 42BD  NRx1 = TRK_DUTY on ch1/ch2 only
    jr nc,.l42C3                                    ; 42BF
    ld a,[hl]                                       ; 42C1
    ldh [c],a                                       ; 42C2
.l42C3:
    inc hl                                          ; 42C3
    res 3,[hl]                                      ; 42C4  clear the release flag
    inc c                                           ; 42C6
    inc c                                           ; 42C7
    inc hl                                          ; 42C8
    ld a,[hli]                                      ; 42C9
    ldh [c],a                                       ; 42CA  NRx3 = period low
    inc c                                           ; 42CB
    ld a,c                                          ; 42CC
    cp $1E                                          ; 42CD  ch3/ch4:
    jr z,.l42D5                                     ; 42CF
    cp $23                                          ; 42D1
    jr nz,.l42DE                                    ; 42D3
.l42D5:
    call Snd_IsChannelOn                            ; 42D5    still running: no retrigger
    jr z,.l42DE                                     ; 42D8
    ld a,[hl]                                       ; 42DA
    ldh [c],a                                       ; 42DB
    jr .l42E2                                       ; 42DC
.l42DE:
    ld a,[hl]                                       ; 42DE  NRx4 = period high + trigger (every frame on ch1/ch2)
    or $80                                          ; 42DF
    ldh [c],a                                       ; 42E1
.l42E2:
    jp Snd_OutputOff.l4359                          ; 42E2
.l42E5:
    pop hl                                          ; 42E5
    ld de,$FFEF                                     ; 42E6
    add hl,de                                       ; 42E9
    res 0,[hl]                                      ; 42EA  no envelope: one-shot. Clear "sounding" so this is written only once
    res 3,[hl]                                      ; 42EC
    dec hl                                          ; 42EE
    ld a,c                                          ; 42EF
    cp $1A                                          ; 42F0  NRx1 = TRK_DUTY on ch1/ch2 only
    jr nc,.l42F8                                    ; 42F2
    ld a,[hl]                                       ; 42F4
    dec c                                           ; 42F5
    ldh [c],a                                       ; 42F6
    inc c                                           ; 42F7
.l42F8:
    push hl                                         ; 42F8
    ld e,b                                          ; 42F9
    ld d,$00                                        ; 42FA
    ld hl,wSndPan                                   ; 42FC  NR51 |= pan
    add hl,de                                       ; 42FF
    ldh a,[rNR51]                                   ; 4300
    or [hl]                                         ; 4302
    ldh [rNR51],a                                   ; 4303
    pop hl                                          ; 4305
    dec hl                                          ; 4306
    dec hl                                          ; 4307
    dec hl                                          ; 4308
    push hl                                         ; 4309
    ld a,[hl]                                       ; 430A  TRK_VOLUME >> 4
    swap a                                          ; 430B
    and $0F                                         ; 430D
    ld de,$001B                                     ; 430F
    add hl,de                                       ; 4312
    add a,[hl]                                      ; 4313  + TRK_VOLOFS, clamped
    cp $10                                          ; 4314
    jr c,.l4321                                     ; 4316
    cp $F0                                          ; 4318
    jr c,.l431F                                     ; 431A
    sub a                                           ; 431C
    jr .l4321                                       ; 431D
.l431F:
    ld a,$0F                                        ; 431F
.l4321:
    pop hl                                          ; 4321
    ld e,a                                          ; 4322
    ld a,c                                          ; 4323
    cp $1C                                          ; 4324  ch3: NR32 from Snd_WaveVolTable
    jr nz,.l4334                                    ; 4326
    ld d,$00                                        ; 4328
    push hl                                         ; 432A
    ld hl,Snd_WaveVolTable                          ; 432B
    add hl,de                                       ; 432E
    ld a,[hl]                                       ; 432F
    ldh [c],a                                       ; 4330
    pop hl                                          ; 4331
    jr .l4338                                       ; 4332
.l4334:
    ld a,e                                          ; 4334
    swap a                                          ; 4335  NRx2 = level << 4
    ldh [c],a                                       ; 4337
.l4338:
    inc c                                           ; 4338
    ld de,$0005                                     ; 4339
    add hl,de                                       ; 433C
    ld a,[hli]                                      ; 433D  NRx3
    ldh [c],a                                       ; 433E
    inc c                                           ; 433F
    ld a,[hl]                                       ; 4340
    or $80                                          ; 4341  NRx4 + trigger
    ldh [c],a                                       ; 4343
    jp Snd_OutputOff.l4359                          ; 4344

; Note not sounding: if a release is pending, take the channel out of NR51.
Snd_OutputOff:
    bit 3,[hl]                                      ; 4347  release pending?
    jr z,.l4359                                     ; 4349
    res 3,[hl]                                      ; 434B
    ld c,b                                          ; 434D
    ld b,$00                                        ; 434E
    ld hl,Snd_NR51ClearMask                         ; 4350  NR51 &= ~channel bits
    add hl,bc                                       ; 4353
    ldh a,[rNR51]                                   ; 4354
    and [hl]                                        ; 4356
    ldh [rNR51],a                                   ; 4357
.l4359:
    ret                                             ; 4359

; nz if NR52 says hardware channel b is still running.
Snd_IsChannelOn:
    ldh a,[rNR52]                                   ; 435A
    push hl                                         ; 435C
    push de                                         ; 435D
    ld e,b                                          ; 435E
    ld d,$00                                        ; 435F
    ld hl,Snd_NR52Mask                              ; 4361  NR52 bit of this channel
    add hl,de                                       ; 4364
    and [hl]                                        ; 4365
    pop de                                          ; 4366
    pop hl                                          ; 4367
    ret                                             ; 4368

; hl = struct. Gate countdown (release at 0, else advance both envelopes), then length countdown (read a row at 0).
Snd_TickTrack:
    ld bc,$0004                                     ; 4369  TRK_GATE
    add hl,bc                                       ; 436C
    ld c,[hl]                                       ; 436D
    inc hl                                          ; 436E
    ld b,[hl]                                       ; 436F
    dec hl                                          ; 4370
    ld a,c                                          ; 4371
    or b                                            ; 4372
    jr z,.l43A2                                     ; 4373  gate already 0: skip
    dec bc                                          ; 4375
    ld [hl],c                                       ; 4376
    inc hl                                          ; 4377
    ld [hl],b                                       ; 4378
    dec hl                                          ; 4379
    ld a,b                                          ; 437A
    or c                                            ; 437B
    jr z,.l438D                                     ; 437C  gate ran out
    ld de,$0017                                     ; 437E
    add hl,de                                       ; 4381
    inc [hl]                                        ; 4382  TRK_VOLENVPOS + 1
    inc hl                                          ; 4383
    inc hl                                          ; 4384
    inc hl                                          ; 4385
    inc [hl]                                        ; 4386  TRK_PITCHPOS + 1
    ld de,$FFE6                                     ; 4387
    add hl,de                                       ; 438A
    jr .l43A2                                       ; 438B
.l438D:
    push hl                                         ; 438D
    ld bc,$0006                                     ; 438E
    add hl,bc                                       ; 4391
    res 0,[hl]                                      ; 4392  release: not sounding, release pending
    set 3,[hl]                                      ; 4394
    ld de,$0011                                     ; 4396
    add hl,de                                       ; 4399
    ld [hl],$00                                     ; 439A  both envelopes back to position 0
    inc hl                                          ; 439C
    inc hl                                          ; 439D
    inc hl                                          ; 439E
    ld [hl],$00                                     ; 439F
    pop hl                                          ; 43A1
.l43A2:
    dec hl                                          ; 43A2
    ld b,[hl]                                       ; 43A3  TRK_LENGTH
    dec hl                                          ; 43A4
    ld c,[hl]                                       ; 43A5
    ld a,c                                          ; 43A6
    or b                                            ; 43A7
    jr z,.l43B3                                     ; 43A8  0: read now
    dec bc                                          ; 43AA
    ld [hl],c                                       ; 43AB
    inc hl                                          ; 43AC
    ld [hl],b                                       ; 43AD
    ld a,b                                          ; 43AE
    dec hl                                          ; 43AF
    or c                                            ; 43B0
    jr nz,.l43B8                                    ; 43B1  not yet 0
.l43B3:
    dec hl                                          ; 43B3
    dec hl                                          ; 43B4
    call Snd_ReadRow                                ; 43B5
.l43B8:
    ret                                             ; 43B8

; hl = struct. Execute commands until a note/tie/rest row.
Snd_ReadRow:
    ld c,[hl]                                       ; 43B9
    inc hl                                          ; 43BA
    ld b,[hl]                                       ; 43BB
    ld a,[bc]                                       ; 43BC  row byte
    cp $80                                          ; 43BD
    jr nc,Snd_DoCommand                             ; 43BF  command
    cp $7D                                          ; 43C1  $7D: the next byte is the note
    jr nz,.l43C7                                    ; 43C3
    inc bc                                          ; 43C5
    ld a,[bc]                                       ; 43C6
.l43C7:
    ld [wSndNote],a                                 ; 43C7  note
    inc bc                                          ; 43CA
    ld a,[bc]                                       ; 43CB  length
    inc bc                                          ; 43CC
    ld e,a                                          ; 43CD
    ld a,[bc]                                       ; 43CE  peek at the next row byte
    ld d,a                                          ; 43CF
    ld a,e                                          ; 43D0
    ld [hl],b                                       ; 43D1  TRK_PTR = that next byte
    dec hl                                          ; 43D2
    ld [hl],c                                       ; 43D3
    ld bc,$0002                                     ; 43D4
    add hl,bc                                       ; 43D7
    ld [hl],a                                       ; 43D8  TRK_LENGTH = length
    inc hl                                          ; 43D9
    inc hl                                          ; 43DA
    ld e,a                                          ; 43DB
    ld a,d                                          ; 43DC
    cp $7E                                          ; 43DD  next byte $7E (tie): gate = length + 1, so no release in between
    jr nz,.l43E2                                    ; 43DF
    inc e                                           ; 43E1
.l43E2:
    ld a,e                                          ; 43E2
    ld [hl],a                                       ; 43E3  TRK_GATE
    ld bc,$0007                                     ; 43E4
    add hl,bc                                       ; 43E7
    ld e,l                                          ; 43E8
    ld d,h                                          ; 43E9
    ld a,[wSndNote]                                 ; 43EA
    ld c,a                                          ; 43ED
    ld a,[wSndRawFlag]                              ; 43EE  never written by the driver (0): this branch is dead
    cp $7D                                          ; 43F1
    jr z,.l440A                                     ; 43F3
    ld a,c                                          ; 43F5
    cp $7E                                          ; 43F6  $7E tie: nothing else
    jr z,.l4423                                     ; 43F8
    cp $7F                                          ; 43FA  $7F rest
    jr z,.l4424                                     ; 43FC
    ld hl,Snd_FreqTable                             ; 43FE
    ld b,$00                                        ; 4401
    ld a,[wSndChIdx]                                ; 4403  struct 3 (music ch4): the byte is the NR43 value
    cp $03                                          ; 4406
    jr nz,.l4412                                    ; 4408
.l440A:
    ld a,c                                          ; 440A
    ld [de],a                                       ; 440B
    inc de                                          ; 440C
    sub a                                           ; 440D
    ld [de],a                                       ; 440E
    jp .l441A                                       ; 440F
.l4412:
    add hl,bc                                       ; 4412  TRK_PERIOD = Snd_FreqTable[note]
    add hl,bc                                       ; 4413
    ld a,[hl]                                       ; 4414
    ld [de],a                                       ; 4415
    inc hl                                          ; 4416
    inc de                                          ; 4417
    ld a,[hl]                                       ; 4418
    ld [de],a                                       ; 4419
.l441A:
    ld l,e                                          ; 441A
    ld h,d                                          ; 441B
    dec hl                                          ; 441C
    dec hl                                          ; 441D
    set 0,[hl]                                      ; 441E  TRK_FLAGS: sounding, bit 2 (never read)
    set 2,[hl]                                      ; 4420
    ret                                             ; 4422
.l4423:
    ret                                             ; 4423
.l4424:
    dec hl                                          ; 4424
    set 3,[hl]                                      ; 4425  rest: release pending, not sounding
    res 0,[hl]                                      ; 4427
    ret                                             ; 4429

; a = command byte $80-$93: jump through Snd_CmdTable with hl = struct, bc -> command.
Snd_DoCommand:
    ld e,l                                          ; 442A  de = struct
    ld d,h                                          ; 442B
    dec de                                          ; 442C
    push bc                                         ; 442D
    sub $80                                         ; 442E  Snd_CmdTable[a - $80]
    ld c,a                                          ; 4430
    ld b,$00                                        ; 4431
    ld hl,Snd_CmdTable                              ; 4433
    add hl,bc                                       ; 4436
    add hl,bc                                       ; 4437
    ld a,[hl]                                       ; 4438
    ld c,a                                          ; 4439
    inc hl                                          ; 443A
    ld a,[hl]                                       ; 443B
    ld h,a                                          ; 443C
    ld l,c                                          ; 443D
    pop bc                                          ; 443E
    jp hl                                           ; 443F

; Command handlers for $80-$93
Snd_CmdTable:
    dw Cmd_End                     ; $80 end
    dw Cmd_Volume                  ; $81 volume
    dw Cmd_LoopStart               ; $82 loop
    dw Cmd_LoopEnd                 ; $83 end loop
    dw Cmd_Wave                    ; $84 wave
    dw Cmd_Jump                    ; $85 jump
    dw Cmd_Call                    ; $86 call
    dw Cmd_Return                  ; $87 return
    dw Cmd_VolEnv                  ; $88 volume envelope
    dw Cmd_PitchEnv                ; $89 pitch envelope
    dw Cmd_PanLeft                 ; $8A pan left
    dw Cmd_PanRight                ; $8B pan right
    dw Cmd_PanCentre               ; $8C pan centre
    dw Cmd_Nop                     ; $8D
    dw Cmd_Nop                     ; $8E
    dw Cmd_Nop                     ; $8F
    dw Cmd_Duty                    ; $90 duty 0
    dw Cmd_Duty                    ; $91 duty 1
    dw Cmd_Duty                    ; $92 duty 2
    dw Cmd_Duty                    ; $93 duty 3

; $8C: pan[struct] = Snd_PanTable[struct] (both sides)
Cmd_PanCentre:
    ld l,e                                          ; 4468
    ld h,d                                          ; 4469
    inc bc                                          ; 446A
    ld [hl],c                                       ; 446B
    inc hl                                          ; 446C
    ld [hl],b                                       ; 446D
    ld a,[wSndChIdx]                                ; 446E
    ld c,a                                          ; 4471
    ld b,$00                                        ; 4472
    ld hl,Snd_PanTable                              ; 4474  pan[struct] = Snd_PanTable[struct]
    add hl,bc                                       ; 4477
    ld a,[hl]                                       ; 4478
    ld hl,wSndPan                                   ; 4479
    add hl,bc                                       ; 447C
    ld [hl],a                                       ; 447D
    ld l,e                                          ; 447E
    ld h,d                                          ; 447F
    jp Snd_ReadRow                                  ; 4480

; $8A: pan[struct] = Snd_PanTable[struct] & $F0 (left only)
Cmd_PanLeft:
    ld l,e                                          ; 4483
    ld h,d                                          ; 4484
    inc bc                                          ; 4485
    ld [hl],c                                       ; 4486
    inc hl                                          ; 4487
    ld [hl],b                                       ; 4488
    ld a,[wSndChIdx]                                ; 4489
    ld c,a                                          ; 448C
    ld b,$00                                        ; 448D
    ld hl,Snd_PanTable                              ; 448F
    add hl,bc                                       ; 4492
    ld a,[hl]                                       ; 4493
    and $F0                                         ; 4494
    ld hl,wSndPan                                   ; 4496
    add hl,bc                                       ; 4499
    ld [hl],a                                       ; 449A
    ld l,e                                          ; 449B
    ld h,d                                          ; 449C
    jp Snd_ReadRow                                  ; 449D

; $8B: pan[struct] = Snd_PanTable[struct] & $0F (right only)
Cmd_PanRight:
    ld l,e                                          ; 44A0
    ld h,d                                          ; 44A1
    inc bc                                          ; 44A2
    ld [hl],c                                       ; 44A3
    inc hl                                          ; 44A4
    ld [hl],b                                       ; 44A5
    ld a,[wSndChIdx]                                ; 44A6
    ld c,a                                          ; 44A9
    ld b,$00                                        ; 44AA
    ld hl,Snd_PanTable                              ; 44AC
    add hl,bc                                       ; 44AF
    ld a,[hl]                                       ; 44B0
    and $0F                                         ; 44B1
    ld hl,wSndPan                                   ; 44B3
    add hl,bc                                       ; 44B6
    ld [hl],a                                       ; 44B7
    ld l,e                                          ; 44B8
    ld h,d                                          ; 44B9
    jp Snd_ReadRow                                  ; 44BA

; NR51 bits per struct (both sides)
Snd_PanTable:
    db $11, $22, $44, $88, $11, $22, $44, $88

; $8D-$8F: no effect
Cmd_Nop:
    ld l,e                                          ; 44C5
    ld h,d                                          ; 44C6
    inc bc                                          ; 44C7
    ld [hl],c                                       ; 44C8
    inc hl                                          ; 44C9
    ld [hl],b                                       ; 44CA
    dec hl                                          ; 44CB
    jp Snd_ReadRow                                  ; 44CC

; $90-$93: TRK_DUTY = (cmd & 3) << 6
Cmd_Duty:
    ld l,e                                          ; 44CF
    ld h,d                                          ; 44D0
    ld a,[bc]                                       ; 44D1  a = the command byte itself
    inc bc                                          ; 44D2
    ld [hl],c                                       ; 44D3
    inc hl                                          ; 44D4
    ld [hl],b                                       ; 44D5
    ld bc,$0008                                     ; 44D6
    add hl,bc                                       ; 44D9
    swap a                                          ; 44DA  (cmd & 3) << 6
    sla a                                           ; 44DC
    sla a                                           ; 44DE
    and $C0                                         ; 44E0
    ld [hl],a                                       ; 44E2
    ld bc,$FFF7                                     ; 44E3
    add hl,bc                                       ; 44E6
    jp Snd_ReadRow                                  ; 44E7

; $89 n: pitch envelope n (PitchEnvTable), from its start
Cmd_PitchEnv:
    ld l,e                                          ; 44EA
    ld h,d                                          ; 44EB
    push hl                                         ; 44EC
    inc bc                                          ; 44ED
    ld a,[bc]                                       ; 44EE
    inc bc                                          ; 44EF
    ld [hl],c                                       ; 44F0
    inc hl                                          ; 44F1
    ld [hl],b                                       ; 44F2
    ld bc,$001D                                     ; 44F3
    add hl,bc                                       ; 44F6
    ld e,l                                          ; 44F7
    ld d,h                                          ; 44F8
    ld c,a                                          ; 44F9
    ld b,$00                                        ; 44FA
    ld hl,PitchEnvTable                             ; 44FC  PitchEnvTable[n]
    add hl,bc                                       ; 44FF
    add hl,bc                                       ; 4500
    sub a                                           ; 4501  TRK_PITCHPOS = 0, TRK_PITCHENV = pointer
    ld [de],a                                       ; 4502
    inc de                                          ; 4503
    ld a,[hli]                                      ; 4504
    ld [de],a                                       ; 4505
    inc de                                          ; 4506
    ld a,[hl]                                       ; 4507
    ld [de],a                                       ; 4508
    pop hl                                          ; 4509
    jp Snd_ReadRow                                  ; 450A

; $88 n: volume envelope n (VolEnvTable), from its start
Cmd_VolEnv:
    ld l,e                                          ; 450D
    ld h,d                                          ; 450E
    push hl                                         ; 450F
    inc bc                                          ; 4510
    ld a,[bc]                                       ; 4511
    inc bc                                          ; 4512
    ld [hl],c                                       ; 4513
    inc hl                                          ; 4514
    ld [hl],b                                       ; 4515
    ld bc,$001A                                     ; 4516
    add hl,bc                                       ; 4519
    ld e,l                                          ; 451A
    ld d,h                                          ; 451B
    ld c,a                                          ; 451C
    ld b,$00                                        ; 451D
    ld hl,VolEnvTable                               ; 451F  VolEnvTable[n]
    add hl,bc                                       ; 4522
    add hl,bc                                       ; 4523
    ld a,$00                                        ; 4524  TRK_VOLENVPOS = 0, TRK_VOLENV = pointer
    ld [de],a                                       ; 4526
    inc de                                          ; 4527
    ld a,[hli]                                      ; 4528
    ld [de],a                                       ; 4529
    inc de                                          ; 452A
    ld a,[hl]                                       ; 452B
    ld [de],a                                       ; 452C
    pop hl                                          ; 452D
    jp Snd_ReadRow                                  ; 452E

; $87: continue at TRK_RETURN
Cmd_Return:
    ld l,e                                          ; 4531
    ld h,d                                          ; 4532
    ld bc,$0018                                     ; 4533
    add hl,bc                                       ; 4536
    ld e,[hl]                                       ; 4537  TRK_PTR = TRK_RETURN
    inc hl                                          ; 4538
    ld d,[hl]                                       ; 4539
    ld bc,$FFE8                                     ; 453A
    add hl,bc                                       ; 453D
    ld [hl],d                                       ; 453E
    dec hl                                          ; 453F
    ld [hl],e                                       ; 4540
    jp Snd_ReadRow                                  ; 4541

; $86 ptr: TRK_RETURN = next row, jump to ptr (one level)
Cmd_Call:
    ld l,e                                          ; 4544
    ld h,d                                          ; 4545
    inc bc                                          ; 4546
    ld a,[bc]                                       ; 4547
    ld e,a                                          ; 4548
    inc bc                                          ; 4549
    ld a,[bc]                                       ; 454A
    ld d,a                                          ; 454B
    inc bc                                          ; 454C
    ld [hl],e                                       ; 454D  TRK_PTR = target
    inc hl                                          ; 454E
    ld [hl],d                                       ; 454F
    dec hl                                          ; 4550
    push hl                                         ; 4551
    ld de,$0018                                     ; 4552
    add hl,de                                       ; 4555
    ld [hl],c                                       ; 4556  TRK_RETURN = after the argument
    inc hl                                          ; 4557
    ld [hl],b                                       ; 4558
    pop hl                                          ; 4559
    jp Snd_ReadRow                                  ; 455A

; $85 ptr: jump
Cmd_Jump:
    ld l,e                                          ; 455D
    ld h,d                                          ; 455E
    inc bc                                          ; 455F
    ld a,[bc]                                       ; 4560
    ld [hl],a                                       ; 4561
    inc hl                                          ; 4562
    inc bc                                          ; 4563
    ld a,[bc]                                       ; 4564
    ld [hl],a                                       ; 4565
    dec hl                                          ; 4566
    jp Snd_ReadRow                                  ; 4567

; $84 n: copy wave n (WaveTable) into wave RAM
Cmd_Wave:
    ld l,e                                          ; 456A
    ld h,d                                          ; 456B
    inc bc                                          ; 456C
    ld a,[bc]                                       ; 456D
    inc bc                                          ; 456E
    ld [hl],c                                       ; 456F
    inc hl                                          ; 4570
    ld [hl],b                                       ; 4571
    dec hl                                          ; 4572
    push hl                                         ; 4573
    ld hl,WaveTable                                 ; 4574  WaveTable[n]
    ld c,a                                          ; 4577
    ld b,$00                                        ; 4578
    add hl,bc                                       ; 457A
    add hl,bc                                       ; 457B
    ld a,[hli]                                      ; 457C
    ld h,[hl]                                       ; 457D
    ld l,a                                          ; 457E
    ldh a,[rNR52]                                   ; 457F
    and $04                                         ; 4581  ch3 running?
    jr z,.l458F                                     ; 4583
    ldh a,[rNR51]                                   ; 4585
    and $BB                                         ; 4587  take it out of NR51
    ldh [rNR51],a                                   ; 4589
    ld a,$00                                        ; 458B
    ldh [rNR32],a                                   ; 458D  NR32 = 0 (mute) while loading
.l458F:
    ld de,_AUD3WAVERAM                              ; 458F  copy 16 bytes
.l4592:
    ld a,[hli]                                      ; 4592
    ld [de],a                                       ; 4593
    inc de                                          ; 4594
    ld a,e                                          ; 4595
    cp $40                                          ; 4596
    jr c,.l4592                                     ; 4598
    ldh a,[rNR32]                                   ; 459A
    and $9F                                         ; 459C  NR32: 100% (other bits kept)
    or $20                                          ; 459E
    ldh [rNR32],a                                   ; 45A0
    pop hl                                          ; 45A2
    jp Snd_ReadRow                                  ; 45A3

; $82 n: push (n, next row) on the loop stack
Cmd_LoopStart:
    ld l,e                                          ; 45A6
    ld h,d                                          ; 45A7
    inc bc                                          ; 45A8
    ld a,[bc]                                       ; 45A9
    inc bc                                          ; 45AA
    ld [hl],c                                       ; 45AB
    inc hl                                          ; 45AC
    ld [hl],b                                       ; 45AD
    dec hl                                          ; 45AE
    push hl                                         ; 45AF
    ld de,$000D                                     ; 45B0  push count, return pointer at TRK_SP
    add hl,de                                       ; 45B3
    ld e,[hl]                                       ; 45B4
    inc hl                                          ; 45B5
    ld d,[hl]                                       ; 45B6
    ld [de],a                                       ; 45B7
    inc de                                          ; 45B8
    ld a,c                                          ; 45B9
    ld [de],a                                       ; 45BA
    inc de                                          ; 45BB
    ld a,b                                          ; 45BC
    ld [de],a                                       ; 45BD
    inc de                                          ; 45BE
    ld [hl],d                                       ; 45BF
    dec hl                                          ; 45C0
    ld [hl],e                                       ; 45C1
    pop hl                                          ; 45C2
    jp Snd_ReadRow                                  ; 45C3

; $83: count-1; jump back while non-zero, else pop
Cmd_LoopEnd:
    ld l,e                                          ; 45C6
    ld h,d                                          ; 45C7
    inc bc                                          ; 45C8
    ld [hl],c                                       ; 45C9
    inc hl                                          ; 45CA
    ld [hl],b                                       ; 45CB
    dec hl                                          ; 45CC
    push hl                                         ; 45CD
    ld de,$000D                                     ; 45CE
    add hl,de                                       ; 45D1
    ld e,[hl]                                       ; 45D2
    inc hl                                          ; 45D3
    ld d,[hl]                                       ; 45D4
    dec de                                          ; 45D5  TRK_SP - 3: the top entry
    dec de                                          ; 45D6
    dec de                                          ; 45D7
    ld a,[de]                                       ; 45D8
    dec a                                           ; 45D9  count - 1
    ld [de],a                                       ; 45DA
    and a                                           ; 45DB
    jr z,.l45EC                                     ; 45DC
    inc de                                          ; 45DE
    ld a,[de]                                       ; 45DF  not 0: TRK_PTR = loop start (entry stays)
    ld c,a                                          ; 45E0
    inc de                                          ; 45E1
    ld a,[de]                                       ; 45E2
    ld b,a                                          ; 45E3
    pop hl                                          ; 45E4
    ld [hl],c                                       ; 45E5
    inc hl                                          ; 45E6
    ld [hl],b                                       ; 45E7
    dec hl                                          ; 45E8
    jp Snd_ReadRow                                  ; 45E9
.l45EC:
    ld [hl],d                                       ; 45EC  0: pop
    dec hl                                          ; 45ED
    ld [hl],e                                       ; 45EE
    pop hl                                          ; 45EF
    jp Snd_ReadRow                                  ; 45F0

; $81 v: TRK_VOLUME high nibble = v
Cmd_Volume:
    ld l,e                                          ; 45F3
    ld h,d                                          ; 45F4
    inc bc                                          ; 45F5
    ld a,[bc]                                       ; 45F6
    inc bc                                          ; 45F7
    ld [hl],c                                       ; 45F8
    inc hl                                          ; 45F9
    ld [hl],b                                       ; 45FA
    dec hl                                          ; 45FB
    push hl                                         ; 45FC
    ld bc,$0006                                     ; 45FD
    add hl,bc                                       ; 4600
    swap a                                          ; 4601  high nibble = v, low nibble kept
    ld c,a                                          ; 4603
    ld a,[hl]                                       ; 4604
    and $0F                                         ; 4605
    or c                                            ; 4607
    ld [hl],a                                       ; 4608
    pop hl                                          ; 4609
    jp Snd_ReadRow                                  ; 460A

; $80: stop this struct
Cmd_End:
    ld l,e                                          ; 460D
    ld h,d                                          ; 460E
    ld bc,$000A                                     ; 460F
    add hl,bc                                       ; 4612
    res 0,[hl]                                      ; 4613  not sounding, no release pending
    res 3,[hl]                                      ; 4615
    ld a,[wSndChIdx]                                ; 4617
    ld c,a                                          ; 461A
    ld b,$00                                        ; 461B
    ld hl,Snd_NR51ClearMask                         ; 461D  NR51 &= ~channel bits
    add hl,bc                                       ; 4620
    ldh a,[rNR51]                                   ; 4621
    and [hl]                                        ; 4623
    ldh [rNR51],a                                   ; 4624
    ld hl,Snd_ActiveClearMask                       ; 4626  clear its bit in wSndActive (no more rows read)
    add hl,bc                                       ; 4629
    ld a,[wSndActive]                               ; 462A
    and [hl]                                        ; 462D
    ld [wSndActive],a                               ; 462E
    ret                                             ; 4631

; wSndActive mask that clears the bit of struct n
Snd_ActiveClearMask:
    db $FE, $FD, $FB, $F7, $EF, $DF, $BF, $7F

